	var r = length(camera);
	var rmu = dot(camera, view_ray);
	let disc = rmu * rmu - r * r + atm.top_radius * atm.top_radius;
	var distance_to_top_atmosphere_boundary = -1.0;
	if (disc >= 0.0) {
		distance_to_top_atmosphere_boundary = -rmu - sqrt(disc);
	}

	if (distance_to_top_atmosphere_boundary > 0.0) {
		camera = camera + view_ray * distance_to_top_atmosphere_boundary;
		r = atm.top_radius;
		rmu += distance_to_top_atmosphere_boundary;
	} else if (r > atm.top_radius) {
		return vec3f(0.0);
	}

	let mu = rmu / r;
	if (RayIntersectsGround(atm, r, mu)) {
		return vec3f(0.0);
	}
	return GetTransmittanceToTopAtmosphereBoundary(
		atm, transmittance_texture, r, mu);
